// O RT 128 × 128 com REPEAT e filtro linear (em luz linear: o buffer é sRGB e o texelFetch já decodifica).
vec4 lerRuido(vec2 uv) {
    vec2 q = uv * 128.0 - 0.5;
    vec2 f = fract(q);
    ivec2 b = ivec2(floor(q));
    vec4 a00 = texelFetch(ruido, (b & 127), 0);
    vec4 a10 = texelFetch(ruido, ((b + ivec2(1, 0)) & 127), 0);
    vec4 a01 = texelFetch(ruido, ((b + ivec2(0, 1)) & 127), 0);
    vec4 a11 = texelFetch(ruido, ((b + ivec2(1, 1)) & 127), 0);
    return mix(mix(a00, a10, f.x), mix(a01, a11, f.x), f.y);
}

// O programa 2 do shader NodeVideo/Effect/grain do Node, conta por conta (tools/nodepassesc/montar.py).
vec4 aplicar(vec2 vs_TEXCOORD0)
{
    vec4 SV_Target0 = vec4(0.0);
    vec4 u_xlat0;
    vec4 u_xlat1;
    vec3 u_xlat2;
    bvec2 u_xlatb2;
    vec4 u_xlat3;
    vec4 u_xlat4;
    vec4 u_xlat5;
    float u_xlat19;

    u_xlat0 = nvFonte( vs_TEXCOORD0.xy);
    u_xlat1.xy = vs_TEXCOORD0.xy + vec2(-0.5, -0.5);
    u_xlat1.xy = u_xlat1.xy * vec2(_scale.x, _scale.y);
    u_xlat1.xyz = lerRuido( u_xlat1.xy).xyz;
    u_xlat2.xyz = u_xlat0.xyz;
    u_xlat2.xyz = clamp(u_xlat2.xyz, 0.0, 1.0);
    u_xlat19 = dot(u_xlat2.xyz, vec3(0.300000012, 0.589999974, 0.109999999));
    u_xlat19 = sqrt(u_xlat19);
    u_xlat2.x = (-_amount) + 1.0;
    u_xlat19 = u_xlat2.x * (-u_xlat19) + 1.0;
    u_xlat1.xyz = u_xlat0.xyz * u_xlat1.xyz;
    u_xlat1.xyz = u_xlat1.xyz * vec3(vec3(_intensity, _intensity, _intensity));
    u_xlat1.xyz = vec3(u_xlat19) * u_xlat1.xyz;
    u_xlat1.xyz = u_xlat1.xyz * vec3(30.0, 30.0, 30.0) + u_xlat0.xyz;
    if(0 != 0) {
        u_xlatb2.xy = equal(ivec4(0, 0, 0, 0), ivec4(1, 1, 0, 0)).xy;
        u_xlat1.w = u_xlat0.w;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = nvFonte( vs_TEXCOORD0.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat5 = u_xlat0 * u_xlat5;
        u_xlat3 = u_xlat3 * u_xlat4 + u_xlat5;
        u_xlat0.x = u_xlat4.x * u_xlat3.w;
        SV_Target0.w = (u_xlatb2.y) ? u_xlat0.x : u_xlat3.w;
        SV_Target0.xyz = u_xlat3.xyz;
    } else {
        SV_Target0.xyz = u_xlat1.xyz;
        SV_Target0.w = u_xlat0.w;
    }
    return SV_Target0;
    return SV_Target0;
}


void main() {
    if (acPass == 0) {
        // O Blit do Node num RT de 128: vs_TEXCOORD0 = o meio do texel.
        vec2 uv = gl_FragCoord.xy / 128.0;
        fragColor = _colored ? ruidoColorido(uv) : ruidoCinza(uv);
        return;
    }
    fragColor = nvVolta(aplicar(nvUvDePe()));
}
